solution.solution.cpp:
#include <algorithm>
#include <cmath>

struct Vector2 { float x, y; };
struct Rectangle { float x, y, width, height; };

bool pointInRect(Vector2 p, Rectangle r)
{
    return p.x >= r.x && p.x < r.x + r.width && p.y >= r.y && p.y < r.y + r.height;
}

bool rectsOverlap(Rectangle a, Rectangle b)
{
    return a.x < b.x + b.width && b.x < a.x + a.width && a.y < b.y + b.height && b.y < a.y + a.height;
}

bool circlesOverlap(Vector2 a, float ra, Vector2 b, float rb)
{
    const float dx{ b.x - a.x }, dy{ b.y - a.y }, r{ ra + rb };
    return dx * dx + dy * dy < r * r;
}

bool circleRect(Vector2 c, float r, Rectangle rect)
{
    const float nx{ std::clamp(c.x, rect.x, rect.x + rect.width) };
    const float ny{ std::clamp(c.y, rect.y, rect.y + rect.height) };
    const float dx{ c.x - nx }, dy{ c.y - ny };
    return dx * dx + dy * dy < r * r;
}

namespace { float cross(Vector2 a, Vector2 b) { return a.x * b.y - a.y * b.x; } }

bool segmentsCross(Vector2 a1, Vector2 a2, Vector2 b1, Vector2 b2, Vector2* where)
{
    const Vector2 r{ a2.x - a1.x, a2.y - a1.y }, s{ b2.x - b1.x, b2.y - b1.y }, q{ b1.x - a1.x, b1.y - a1.y };
    const float d{ cross(r, s) };
    if (d == 0) return false;
    const float t{ cross(q, s) / d }, u{ cross(q, r) / d };
    if (t < 0 || t > 1 || u < 0 || u > 1) return false;
    if (where) *where = { a1.x + t * r.x, a1.y + t * r.y };
    return true;
}

unitTests:
TEST("point in rectangle") { const Rectangle r{ 10, 10, 20, 20 }; CHECK(pointInRect({ 10, 10 }, r)); CHECK(pointInRect({ 29.9f, 15 }, r)); CHECK(!pointInRect({ 30, 15 }, r)); CHECK(!pointInRect({ 15, 30 }, r)); }
TEST("rectangles") { const Rectangle a{ 0, 0, 10, 10 }; CHECK(rectsOverlap(a, { 5, 5, 10, 10 })); CHECK(!rectsOverlap(a, { 10, 0, 5, 5 })); CHECK(!rectsOverlap(a, { 0, 10, 5, 5 })); CHECK(rectsOverlap(a, { 2, 2, 1, 1 })); CHECK(!rectsOverlap(a, { -20, 0, 5, 5 })); }
TEST("circles") { CHECK(circlesOverlap({ 0, 0 }, 5, { 8, 0 }, 4)); CHECK(!circlesOverlap({ 0, 0 }, 5, { 9, 0 }, 4)); CHECK(!circlesOverlap({ 0, 0 }, 5, { 7, 7 }, 4)); }
TEST("circle and rectangle") {
    const Rectangle r{ 10, 10, 20, 10 };
    CHECK(circleRect({ 5, 15 }, 6, r)); CHECK(!circleRect({ 5, 15 }, 5, r)); CHECK(circleRect({ 20, 15 }, 1, r));
    CHECK(!circleRect({ 6, 6 }, 5, r)); CHECK(circleRect({ 7, 7 }, 5, r));
}
TEST("segments") {
    Vector2 p{ 0, 0 };
    CHECK(segmentsCross({ 0, 0 }, { 10, 10 }, { 0, 10 }, { 10, 0 }, &p)); CHECK_NEAR(p.x, 5.0, 1e-4); CHECK_NEAR(p.y, 5.0, 1e-4);
    CHECK(!segmentsCross({ 0, 0 }, { 4, 4 }, { 0, 10 }, { 10, 0 }, nullptr));
    CHECK(!segmentsCross({ 0, 0 }, { 10, 0 }, { 0, 1 }, { 10, 1 }, &p));
    CHECK(segmentsCross({ 0, 5 }, { 20, 5 }, { 15, 0 }, { 15, 10 }, &p)); CHECK_NEAR(p.x, 15.0, 1e-4);
}

